/**
 * Types and constants for consent_template_note_mappings.
 *
 * The AFTER INSERT trigger on consent_form_submissions handles actual note
 * propagation in the database — this module only covers the staff-facing
 * CRUD API helpers and shared label maps.
 */
import type { Database } from '@/lib/supabase/types'

export type NoteCategory =
  Database['public']['Tables']['consent_template_note_mappings']['Row']['note_category']

export type NoteMapping =
  Database['public']['Tables']['consent_template_note_mappings']['Row']

export type NoteMappingInsert =
  Database['public']['Tables']['consent_template_note_mappings']['Insert']

export type NoteMappingUpdate =
  Database['public']['Tables']['consent_template_note_mappings']['Update']

export const NOTE_CATEGORY_LABELS: Record<NoteCategory, string> = {
  allergies: 'Allergies',
  medical: 'Medical',
  skin: 'Skin',
  emergency_contact: 'Emergency Contact',
  general: 'General',
}

export const NOTE_CATEGORY_OPTIONS = Object.entries(NOTE_CATEGORY_LABELS).map(
  ([value, label]) => ({ value: value as NoteCategory, label }),
)

/**
 * GET  /api/consent-template-mappings?template_id=<uuid>
 *   List all section→note mappings for a template (studio-scoped).
 *
 * POST /api/consent-template-mappings
 *   Upsert a single mapping. Body: { template_id, section_id, note_category, note_prefix?, is_pinned? }
 *   Upsert key: (template_id, section_id) — one mapping per section.
 *
 * Auth: owner or admin only.
 */
import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const UpsertMappingSchema = z.object({
  template_id: z.string().uuid(),
  section_id: z.string().min(1).max(50),
  note_category: z.enum(['allergies', 'medical', 'skin', 'emergency_contact', 'general']),
  note_prefix: z.string().max(200).nullable().optional(),
  is_pinned: z.boolean().optional(),
})

export async function GET(request: NextRequest) {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  const templateId = request.nextUrl.searchParams.get('template_id')
  if (!templateId) return NextResponse.json({ error: 'template_id required' }, { status: 400 })

  const supabase = await createClient()
  const { data, error } = await supabase
    .from('consent_template_note_mappings')
    .select('*')
    .eq('template_id', templateId)
    .eq('studio_id', auth.studioId)
    .order('created_at')

  if (error) {
    logger.error({ err: error, templateId }, 'note-mappings: GET failed')
    return NextResponse.json({ error: 'database_error' }, { status: 500 })
  }

  return NextResponse.json({ data })
}

export async function POST(request: NextRequest) {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  let rawBody: unknown
  try {
    rawBody = await request.json()
  } catch {
    return NextResponse.json({ error: 'invalid_json' }, { status: 400 })
  }

  const parsed = UpsertMappingSchema.safeParse(rawBody)
  if (!parsed.success) {
    return NextResponse.json({ error: 'validation_error', details: parsed.error.flatten() }, { status: 400 })
  }

  const { template_id, section_id, note_category, note_prefix, is_pinned } = parsed.data

  // Verify template belongs to this studio
  const supabase = await createClient()
  const { data: template, error: templateErr } = await supabase
    .from('consent_form_templates')
    .select('id')
    .eq('id', template_id)
    .eq('studio_id', auth.studioId)
    .single()

  if (templateErr ?? !template) {
    return NextResponse.json({ error: 'template_not_found' }, { status: 404 })
  }

  // Build upsert payload — exactOptionalPropertyTypes: never spread undefined optional keys
  const upsertPayload: {
    studio_id: string
    template_id: string
    section_id: string
    note_category: typeof note_category
    note_prefix: string | null
    is_pinned: boolean
    updated_at: string
  } = {
    studio_id: auth.studioId,
    template_id,
    section_id,
    note_category,
    note_prefix: note_prefix ?? null,
    is_pinned: is_pinned ?? true,
    updated_at: new Date().toISOString(),
  }

  const { data, error } = await supabase
    .from('consent_template_note_mappings')
    .upsert(upsertPayload, { onConflict: 'template_id,section_id' })
    .select()
    .single()

  if (error) {
    logger.error({ err: error, template_id, section_id }, 'note-mappings: upsert failed')
    return NextResponse.json({ error: 'database_error' }, { status: 500 })
  }

  return NextResponse.json({ data }, { status: 201 })
}

/**
 * DELETE /api/consent-template-mappings/[id]
 *   Remove a section→note propagation mapping (studio-scoped, owner/admin only).
 */
import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface RouteParams {
  params: Promise<{ id: string }>
}

export async function DELETE(request: NextRequest, { params }: RouteParams) {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const { id } = await params
  const supabase = await createClient()

  const { error } = await supabase
    .from('consent_template_note_mappings')
    .delete()
    .eq('id', id)
    .eq('studio_id', auth.studioId)

  if (error) {
    logger.error({ err: error, id }, 'note-mappings: DELETE failed')
    return NextResponse.json({ error: 'database_error' }, { status: 500 })
  }

  return NextResponse.json({ success: true })
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Clock, ClipboardList } from 'lucide-react'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import { Switch } from '@/components/ui/switch'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Typography } from '@/components/ui/typography'
import type { Database } from '@/lib/supabase/types'

type Studio = Pick<
  Database['public']['Tables']['studios']['Row'],
  | 'id'
  | 'deposit_deadline_hours'
  | 'require_intake_before_booking'
  | 'default_intake_template_id'
  | 'intake_timing'
>

interface ConsentTemplate {
  id: string
  name: string
  kind: string
}

interface BookingPoliciesClientProps {
  studio: Studio
  isOwner: boolean
  consentTemplates: ConsentTemplate[]
}

export function BookingPoliciesClient({
  studio,
  isOwner,
  consentTemplates,
}: BookingPoliciesClientProps) {
  const router = useRouter()

  // Deposit policy
  const [deadlineHours, setDeadlineHours] = useState<number>(studio.deposit_deadline_hours)

  // Intake policy
  const [requireIntake, setRequireIntake] = useState(studio.require_intake_before_booking)
  const [defaultTemplateId, setDefaultTemplateId] = useState<string>(
    studio.default_intake_template_id ?? '',
  )
  const [intakeTiming, setIntakeTiming] = useState<'pre_booking' | 'post_booking'>(
    studio.intake_timing,
  )

  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)

  // Track dirty state
  useEffect(() => {
    const changed =
      deadlineHours !== studio.deposit_deadline_hours ||
      requireIntake !== studio.require_intake_before_booking ||
      defaultTemplateId !== (studio.default_intake_template_id ?? '') ||
      intakeTiming !== studio.intake_timing
    setDirty(changed)
  }, [
    deadlineHours,
    requireIntake,
    defaultTemplateId,
    intakeTiming,
    studio,
  ])

  function handleHoursChange(raw: string) {
    const parsed = parseInt(raw, 10)
    if (!Number.isNaN(parsed)) setDeadlineHours(parsed)
  }

  async function handleSave() {
    if (!isOwner) return

    const clamped = Math.min(168, Math.max(1, deadlineHours))
    if (clamped !== deadlineHours) setDeadlineHours(clamped)

    // Validate: if intake required, a template must be selected
    if (requireIntake && !defaultTemplateId) {
      toast.error('Select a default intake template before enabling intake requirement')
      return
    }

    setSaving(true)
    try {
      const body: Record<string, unknown> = {
        deposit_deadline_hours: clamped,
        require_intake_before_booking: requireIntake,
        default_intake_template_id: requireIntake ? defaultTemplateId : null,
        intake_timing: intakeTiming,
      }

      const res = await fetch(`/api/studios/${studio.id}/policies`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to save')
      }

      toast.success('Booking policies saved')
      setDirty(false)
      router.refresh()
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'An error occurred')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div className="space-y-1">
          <Typography variant="h1">Booking Policies</Typography>
          <p className="text-sm text-muted-foreground">
            Set deposit requirements, cancellation rules, and intake form behaviour.
            Changes apply to new bookings only.
          </p>
        </div>
        {dirty && isOwner && (
          <span className="text-xs text-muted-foreground mt-1">Unsaved changes</span>
        )}
      </div>

      <Separator />

      {/* ── Deposit & Auto-cancel ────────────────────────────────────── */}
      <div className="space-y-6">
        <div>
          <h2 className="text-sm font-semibold">Deposits &amp; Auto-cancel</h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Control how long clients have to pay their deposit before the slot is released.
          </p>
        </div>

        <div className="space-y-3 max-w-xs">
          <Label htmlFor="deposit-deadline" className="text-sm font-medium">
            <span className="flex items-center gap-1.5">
              <Clock className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
              Hold slot for (hours awaiting deposit)
            </span>
          </Label>
          <Input
            id="deposit-deadline"
            type="number"
            min={1}
            max={168}
            value={deadlineHours}
            onChange={(e) => handleHoursChange(e.target.value)}
            disabled={!isOwner}
            className="w-32 tabular-nums"
            aria-describedby="deposit-deadline-desc"
          />
          <p id="deposit-deadline-desc" className="text-xs text-muted-foreground leading-relaxed max-w-sm">
            If the deposit is not paid within this window, the booking is automatically
            cancelled and the slot is freed. Minimum 1 hour, maximum 168 hours (7 days).
          </p>

          <div className="inline-flex items-center gap-1.5 text-xs text-muted-foreground bg-muted/40 rounded-md px-2.5 py-1.5">
            <span>Current window:</span>
            <span className="font-semibold tabular-nums text-foreground">
              {deadlineHours >= 24
                ? `${(deadlineHours / 24).toFixed(deadlineHours % 24 === 0 ? 0 : 1)} day${deadlineHours === 24 ? '' : 's'}`
                : `${deadlineHours} hour${deadlineHours === 1 ? '' : 's'}`}
            </span>
          </div>
        </div>
      </div>

      <Separator />

      {/* ── Intake form policy ────────────────────────────────────────── */}
      <div className="space-y-6">
        <div>
          <h2 className="text-sm font-semibold flex items-center gap-1.5">
            <ClipboardList className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
            Client Intake Form
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Require clients to complete a consent/intake form as part of the booking process.
            Answers automatically populate the client&apos;s health notes.
          </p>
        </div>

        <div className="flex items-center gap-3">
          <Switch
            id="require-intake"
            checked={requireIntake}
            onCheckedChange={(v) => setRequireIntake(v)}
            disabled={!isOwner}
            aria-describedby="require-intake-desc"
          />
          <Label htmlFor="require-intake" className="text-sm cursor-pointer">
            Require intake form before each booking
          </Label>
        </div>
        <p id="require-intake-desc" className="text-xs text-muted-foreground -mt-4 ml-11">
          When enabled, clients must complete the selected form during or after booking.
        </p>

        {requireIntake && (
          <div className="ml-11 space-y-6">
            {/* Default template */}
            <div className="space-y-2">
              <Label className="text-sm font-medium">Default intake template</Label>
              <Select
                value={defaultTemplateId}
                onValueChange={(v) => setDefaultTemplateId(v)}
                disabled={!isOwner}
              >
                <SelectTrigger className="w-72">
                  <SelectValue placeholder="Select a template…" />
                </SelectTrigger>
                <SelectContent>
                  {consentTemplates.length === 0 ? (
                    <SelectItem value="__none" disabled>
                      No templates available — create one first
                    </SelectItem>
                  ) : (
                    consentTemplates.map((t) => (
                      <SelectItem key={t.id} value={t.id}>
                        {t.name}
                        <span className="ml-2 text-xs text-muted-foreground capitalize">
                          ({t.kind})
                        </span>
                      </SelectItem>
                    ))
                  )}
                </SelectContent>
              </Select>
              <p className="text-xs text-muted-foreground">
                This template is sent or shown to every new booking from this studio.
              </p>
            </div>

            {/* Timing */}
            <div className="space-y-2">
              <Label className="text-sm font-medium">When to show the intake form</Label>
              <RadioGroup
                value={intakeTiming}
                onValueChange={(v) => setIntakeTiming(v as 'pre_booking' | 'post_booking')}
                disabled={!isOwner}
                className="space-y-2"
              >
                <div className="flex items-start gap-3 rounded-lg border border-border p-3 hover:bg-muted/30 transition-colors">
                  <RadioGroupItem value="pre_booking" id="timing-pre" className="mt-0.5" />
                  <Label htmlFor="timing-pre" className="cursor-pointer space-y-0.5">
                    <span className="text-sm font-medium">Show inline during booking (pre-booking)</span>
                    <p className="text-xs text-muted-foreground font-normal">
                      Client completes the intake form on the booking page before confirming.
                      The booking is created only after the form is signed.
                    </p>
                  </Label>
                </div>

                <div className="flex items-start gap-3 rounded-lg border border-border p-3 hover:bg-muted/30 transition-colors">
                  <RadioGroupItem value="post_booking" id="timing-post" className="mt-0.5" />
                  <Label htmlFor="timing-post" className="cursor-pointer space-y-0.5">
                    <span className="text-sm font-medium">Send email link after booking (post-booking)</span>
                    <p className="text-xs text-muted-foreground font-normal">
                      The booking is confirmed immediately. A signing link is emailed to the
                      client after booking completes.
                    </p>
                  </Label>
                </div>
              </RadioGroup>
            </div>
          </div>
        )}
      </div>

      {isOwner && (
        <>
          <Separator />
          <div className="flex justify-end">
            <Button
              onClick={() => void handleSave()}
              disabled={saving || !dirty}
              size="sm"
            >
              {saving ? 'Saving…' : 'Save changes'}
            </Button>
          </div>
        </>
      )}

      {!isOwner && (
        <p className="text-xs text-muted-foreground">
          Only studio owners and admins can change booking policies.
        </p>
      )}
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { Skeleton } from '@/components/ui/skeleton'
import { BookingPoliciesClient } from './_components/BookingPoliciesClient'

export const metadata: Metadata = {
  title: 'Booking Policies — Settings — InkOS',
}

async function BookingPoliciesContent() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  const [studioResult, templatesResult] = await Promise.all([
    supabase
      .from('studios')
      .select(
        'id, deposit_deadline_hours, require_intake_before_booking, default_intake_template_id, intake_timing',
      )
      .eq('id', auth.studioId)
      .single(),
    supabase
      .from('consent_form_templates')
      .select('id, name, kind')
      .eq('studio_id', auth.studioId)
      .eq('is_active', true)
      .order('name'),
  ])

  if (studioResult.error ?? !studioResult.data) redirect('/dashboard')

  const studio = studioResult.data
  const consentTemplates = templatesResult.data ?? []

  return (
    <BookingPoliciesClient
      studio={{
        id: studio.id,
        deposit_deadline_hours: studio.deposit_deadline_hours,
        require_intake_before_booking: studio.require_intake_before_booking,
        default_intake_template_id: studio.default_intake_template_id,
        intake_timing: studio.intake_timing,
      }}
      isOwner={auth.role === 'owner' || auth.role === 'admin'}
      consentTemplates={consentTemplates}
    />
  )
}

export default function BookingPoliciesPage() {
  return (
    <Suspense
      fallback={
