/**
 * PATCH /api/studios/[id]/policies
 *
 * Updates studio-level booking policies (deposit_deadline_hours, intake policy).
 * Auth guard: owner or admin role only.
 * Rate limited: authedRatelimit (10 req/min per user).
 */
import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const bodySchema = z
  .object({
    deposit_deadline_hours: z
      .number({ invalid_type_error: 'deposit_deadline_hours must be a number' })
      .int()
      .min(1, 'Minimum 1 hour')
      .max(168, 'Maximum 168 hours (7 days)')
      .optional(),
    require_intake_before_booking: z.boolean().optional(),
    default_intake_template_id: z.string().uuid().nullable().optional(),
    intake_timing: z.enum(['pre_booking', 'post_booking']).optional(),
  })
  .refine(
    (d) => {
      // If enabling intake, a template must be provided (or null to disable)
      if (d.require_intake_before_booking === true && d.default_intake_template_id === null) {
        return false
      }
      return true
    },
    { message: 'default_intake_template_id is required when require_intake_before_booking is true' },
  )

interface RouteParams {
  params: Promise<{ id: string }>
}

export async function PATCH(req: NextRequest, { params }: RouteParams) {
  const { id: studioId } = await params

  // ── Rate limit ──────────────────────────────────────────────────────────────
  const ip = req.headers.get('x-forwarded-for') ?? '127.0.0.1'
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  // ── Auth ────────────────────────────────────────────────────────────────────
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // ── Authorization: owner or admin only ─────────────────────────────────────
  if (auth.studioId !== studioId) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'Only owners and admins can change booking policies' }, { status: 403 })
  }

  // ── Parse body ──────────────────────────────────────────────────────────────
  let rawBody: unknown
  try {
    rawBody = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const parsed = bodySchema.safeParse(rawBody)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.errors.map((e) => e.message).join(', ') },
      { status: 422 },
    )
  }

  // Build update payload — only include provided fields
  const update: Record<string, unknown> = { updated_at: new Date().toISOString() }

  if (parsed.data.deposit_deadline_hours !== undefined) {
    update['deposit_deadline_hours'] = parsed.data.deposit_deadline_hours
  }
  if (parsed.data.require_intake_before_booking !== undefined) {
    update['require_intake_before_booking'] = parsed.data.require_intake_before_booking
  }
  if ('default_intake_template_id' in parsed.data) {
    update['default_intake_template_id'] = parsed.data.default_intake_template_id
  }
  if (parsed.data.intake_timing !== undefined) {
    update['intake_timing'] = parsed.data.intake_timing
  }

  // ── Update ──────────────────────────────────────────────────────────────────
  const supabase = await createClient()
  const { error } = await supabase
    .from('studios')
    .update(update)
    .eq('id', studioId)

  if (error) {
    logger.error({ err: error, studioId }, 'policies: DB update failed')
    return NextResponse.json({ error: 'Failed to save policies' }, { status: 500 })
  }

  logger.info({ studioId, ...parsed.data }, 'policies: updated')
  return NextResponse.json({ ok: true })
}

