/**
 * NoteMappingEditor — collapsible per-section UI for configuring
 * whether a template section's answer propagates to client_notes.
 *
 * Used inside TemplateBuilder's section list, rendered below each section card.
 */

import { useState, useCallback } from 'react'
import { ChevronDown, ChevronRight, Loader2, AlertCircle } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { cn } from '@/lib/utils'
import { NOTE_CATEGORY_OPTIONS } from '@/lib/consent/note-mappings'
import type { NoteCategory, NoteMapping } from '@/lib/consent/note-mappings'

interface NoteMappingEditorProps {
  /** Template ID (needed to call API) */
  templateId: string
  /** Section ID (nanoid) */
  sectionId: string
  /** Section label — shown in the collapsible header */
  sectionLabel: string
  /** Existing mapping for this section, if any */
  existingMapping: NoteMapping | null
  /** Fired after a mapping is saved or deleted */
  onMappingChange: (sectionId: string, mapping: NoteMapping | null) => void
}

export function NoteMappingEditor({
  templateId,
  sectionId,
  sectionLabel,
  existingMapping,
  onMappingChange,
}: NoteMappingEditorProps) {
  const [expanded, setExpanded] = useState(false)
  const [enabled, setEnabled] = useState(existingMapping !== null)
  const [category, setCategory] = useState<NoteCategory>(
    existingMapping?.note_category ?? 'general',
  )
  const [prefix, setPrefix] = useState(existingMapping?.note_prefix ?? '')
  const [isPinned, setIsPinned] = useState(existingMapping?.is_pinned ?? true)
  const [saving, setSaving] = useState(false)
  const [deleting, setDeleting] = useState(false)

  const handleSave = useCallback(async () => {
    if (!templateId) {
      toast.error('Save the template first before configuring note propagation')
      return
    }

    setSaving(true)
    try {
      const res = await fetch('/api/consent-template-mappings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          template_id: templateId,
          section_id: sectionId,
          note_category: category,
          note_prefix: prefix.trim() || null,
          is_pinned: isPinned,
        }),
      })

      if (!res.ok) {
        const body = await res.json() as { error?: string }
        throw new Error(body.error ?? 'Failed to save mapping')
      }

      const { data } = await res.json() as { data: NoteMapping }
      onMappingChange(sectionId, data)
      toast.success('Note mapping saved')
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Failed to save mapping')
    } finally {
      setSaving(false)
    }
  }, [templateId, sectionId, category, prefix, isPinned, onMappingChange])

  const handleDisable = useCallback(async () => {
    if (!existingMapping) {
      setEnabled(false)
      return
    }

    setDeleting(true)
    try {
      const res = await fetch(`/api/consent-template-mappings/${existingMapping.id}`, {
        method: 'DELETE',
      })

      if (!res.ok) {
        const body = await res.json() as { error?: string }
        throw new Error(body.error ?? 'Failed to remove mapping')
      }

      onMappingChange(sectionId, null)
      setEnabled(false)
      toast.success('Note propagation disabled')
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Failed to remove mapping')
    } finally {
      setDeleting(false)
    }
  }, [existingMapping, sectionId, onMappingChange])

  function handleToggle(checked: boolean) {
    if (!checked && existingMapping) {
      void handleDisable()
    } else {
      setEnabled(checked)
    }
  }

  const hasMapping = existingMapping !== null

  return (
    <div className="mt-1.5 rounded-md border border-border/60 bg-muted/20">
      {/* Collapsible trigger */}
      <button
        type="button"
        className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs text-muted-foreground hover:text-foreground transition-colors"
        onClick={() => setExpanded((v) => !v)}
        aria-expanded={expanded}
      >
        {expanded ? (
          <ChevronDown className="h-3.5 w-3.5 shrink-0" />
        ) : (
          <ChevronRight className="h-3.5 w-3.5 shrink-0" />
        )}
        <span className="truncate min-w-0">
          Propagate to medical notes
          {hasMapping && (
            <span className="ml-1.5 text-primary font-medium">
              ({NOTE_CATEGORY_OPTIONS.find((o) => o.value === existingMapping.note_category)?.label ?? existingMapping.note_category})
            </span>
          )}
        </span>
        {hasMapping && (
          <span className="ml-auto shrink-0 h-1.5 w-1.5 rounded-full bg-primary" aria-hidden="true" />
        )}
      </button>

      {/* Expanded content */}
      {expanded && (
        <div className="border-t border-border/60 px-3 py-3 space-y-3">
          {/* Enable toggle */}
          <div className="flex items-center justify-between">
            <Label className="text-xs">
              Auto-create client note from &ldquo;{sectionLabel}&rdquo; answer
            </Label>
            <Switch
              checked={enabled}
              onCheckedChange={handleToggle}
              disabled={deleting}
              aria-label="Enable note propagation"
            />
          </div>

          {enabled && (
            <>
              {!templateId && (
                <div className="flex items-center gap-1.5 rounded-md bg-warning/10 border border-warning/20 px-2.5 py-1.5 text-xs text-warning-foreground">
                  <AlertCircle className="h-3.5 w-3.5 shrink-0" />
                  Save the template first to enable note mapping.
                </div>
              )}

              {/* Category */}
              <div className="space-y-1.5">
                <Label htmlFor={`note-cat-${sectionId}`} className="text-xs">
                  Note category
                </Label>
                <Select
                  value={category}
                  onValueChange={(v) => setCategory(v as NoteCategory)}
                >
                  <SelectTrigger
                    id={`note-cat-${sectionId}`}
                    className="h-8 text-xs"
                  >
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {NOTE_CATEGORY_OPTIONS.map((opt) => (
                      <SelectItem key={opt.value} value={opt.value} className="text-xs">
                        {opt.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* Prefix */}
              <div className="space-y-1.5">
                <Label htmlFor={`note-prefix-${sectionId}`} className="text-xs">
                  Note prefix <span className="text-muted-foreground">(optional)</span>
                </Label>
                <Input
                  id={`note-prefix-${sectionId}`}
                  value={prefix}
                  onChange={(e) => setPrefix(e.target.value)}
                  placeholder="e.g. Allergy:"
                  className="h-8 text-xs"
                  maxLength={200}
                />
                <p className="text-[10px] text-muted-foreground">
                  Prepended to the answer when creating the note body.
                </p>
              </div>

              {/* Pinned toggle */}
              <div className="flex items-center justify-between">
                <Label
                  htmlFor={`note-pinned-${sectionId}`}
                  className={cn('text-xs cursor-pointer')}
                >
                  Pin note (shows as health alert)
                </Label>
                <Switch
                  id={`note-pinned-${sectionId}`}
                  checked={isPinned}
                  onCheckedChange={setIsPinned}
                  aria-label="Pin note"
                />
              </div>

              {/* Save button */}
              <div className="flex justify-end pt-1">
                <Button
                  type="button"
                  size="sm"
                  variant="secondary"
                  className="h-7 text-xs gap-1.5"
                  onClick={() => void handleSave()}
                  disabled={saving || !templateId}
                >
                  {saving && (
                    <Loader2 aria-hidden="true" className="h-3 w-3 animate-spin" />
                  )}
                  {existingMapping ? 'Update mapping' : 'Save mapping'}
                </Button>
              </div>
            </>
          )}
        </div>
      )}
    </div>
  )
}

