const TEMPLATE_KIND_LABELS: Record<TemplateKind, string> = {
  tattoo: 'Tattoo',
  piercing: 'Piercing',
  pmu: 'PMU',
  touch_up: 'Touch-up',
  minor: 'Minor (under 18)',
  custom: 'Custom',
}

const RETENTION_YEARS_OPTIONS = [3, 5, 7, 10] as const

interface SavePayload {
  name: string
  kind: TemplateKind
  sections: ConsentSection[]
  retention_years: number
  is_default: boolean
  language: string
  required_for_booking: boolean
  requires_guardian: boolean
}

interface TemplateBuilderProps {
  /** When provided, we're editing an existing template */
  templateId?: string
  /** Pre-populated values for edit mode */
  initialValues?: Partial<SavePayload>
  /** Current submission count — used to detect immutability violation risk */
  submissionCount?: number
  /** Called after successful save — receives new/updated template id */
  onSave?: (id: string) => void
}

export function TemplateBuilder({
  templateId,
  initialValues,
  submissionCount = 0,
  onSave,
}: TemplateBuilderProps) {
  const [name, setName] = useState(initialValues?.name ?? '')
  const [kind, setKind] = useState<TemplateKind>(initialValues?.kind ?? 'tattoo')
  const [sections, setSections] = useState<ConsentSection[]>(initialValues?.sections ?? [])
  const [retentionYears, setRetentionYears] = useState<number>(
    initialValues?.retention_years ?? 7
  )
  const [isDefault, setIsDefault] = useState(initialValues?.is_default ?? false)
  const [language, setLanguage] = useState(initialValues?.language ?? 'en')
  const [requiredForBooking, setRequiredForBooking] = useState(
    initialValues?.required_for_booking ?? false
  )
  const [requiresGuardian, setRequiresGuardian] = useState(
    initialValues?.requires_guardian ?? false
  )
  const [showPreview, setShowPreview] = useState(false)

  // ── Note mappings (section_id → NoteMapping | null) ────────────────────────
  const [noteMappings, setNoteMappings] = useState<Record<string, NoteMapping | null>>({})
  const [showNoteMappings, setShowNoteMappings] = useState(false)

  // Load existing note mappings when editing a saved template
  useEffect(() => {
    if (!templateId) return
    void (async () => {
      try {
        const res = await fetch(`/api/consent-template-mappings?template_id=${templateId}`)
        if (!res.ok) return
        const { data } = await res.json() as { data: NoteMapping[] }
        const map: Record<string, NoteMapping | null> = {}
        for (const m of data) {
          map[m.section_id] = m
        }
        setNoteMappings(map)
      } catch {
        // non-fatal — note mappings UI just starts empty
      }
    })()
  }, [templateId])

  const handleMappingChange = useCallback((sectionId: string, mapping: NoteMapping | null) => {
    setNoteMappings((prev) => ({ ...prev, [sectionId]: mapping }))
  }, [])

  // Immutability violation dialog
  const [immutabilityDialog, setImmutabilityDialog] = useState<{
    open: boolean
    newVersion: number
  }>({ open: false, newVersion: 0 })

  const [isPending, startTransition] = useTransition()

  const handleAddSection = useCallback((sectionKind: ConsentSectionKind) => {
    const factory = DEFAULT_SECTION_FOR_KIND[sectionKind]
    const newSection = factory()
    setSections((prev) => {
      const order = prev.length
      return [...prev, { ...newSection, order }]
    })
  }, [])

  const doSave = useCallback(
    async (forceNewVersion = false) => {
      if (!name.trim()) {
        toast.error('Template name is required')
        return
      }
      if (sections.length === 0) {
        toast.error('Add at least one section before saving')
        return
      }

      const payload: SavePayload = {
        name: name.trim(),
        kind,
        sections,
        retention_years: retentionYears,
        is_default: isDefault,
        language,
        required_for_booking: requiredForBooking,
        requires_guardian: requiresGuardian,
      }

      const url =
        templateId && !forceNewVersion
          ? `/api/consent-forms/templates/${templateId}`
          : '/api/consent-forms/templates'

      const method = templateId && !forceNewVersion ? 'PATCH' : 'POST'

      let res: Response
      try {
        res = await fetch(url, {
          method,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })
      } catch {
        toast.error('Network error — please try again')
        return
      }

      if (res.status === 409) {
        const body = (await res.json()) as { error: string; new_version?: number }
        if (body.error === 'immutability_violation' && body.new_version) {
          setImmutabilityDialog({ open: true, newVersion: body.new_version })
          return
        }
        toast.error(body.error === 'slug_conflict' ? 'A template with this name already exists' : 'Conflict — please refresh')
        return
      }

      if (!res.ok) {
        const body = (await res.json().catch(() => ({ error: 'Unknown error' }))) as { error?: string }
        toast.error(body.error ?? 'Failed to save template')
        return
      }

      const result = (await res.json()) as { id: string }
      toast.success(forceNewVersion ? 'New version published' : templateId ? 'Template saved' : 'Template created')
      onSave?.(result.id)
    },
    [
      name,
      kind,
      sections,
      retentionYears,
      isDefault,
      language,
      requiredForBooking,
      requiresGuardian,
      templateId,
      onSave,
    ]
  )

  const handleSave = useCallback(() => {
    startTransition(() => { void doSave(false) })
  }, [doSave])

  const handlePublishNewVersion = useCallback(() => {
    setImmutabilityDialog({ open: false, newVersion: 0 })
    startTransition(() => { void doSave(true) })
  }, [doSave])

  // Sections that support answer propagation (exclude structural/display-only)
  const propagatableSectionKinds: ConsentSection['kind'][] = [
    'text_input',
    'checkbox',
    'date',
    'dropdown',
    'initials',
  ]
  const propagatableSections = sections.filter((s) =>
    propagatableSectionKinds.includes(s.kind),
  )

  const activeMappingCount = Object.values(noteMappings).filter(Boolean).length

  return (
    <div className="flex h-full flex-col overflow-hidden">
      {/* ── Top bar ─────────────────────────────────────────────── */}
      <div className="flex shrink-0 items-center gap-3 border-b border-border bg-card px-4 py-3">
        <div className="flex flex-1 items-center gap-3 min-w-0">
          <Input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Template name…"
            className="h-8 w-56 text-sm font-medium"
          />

          <Select value={kind} onValueChange={(v) => setKind(v as TemplateKind)}>
            <SelectTrigger className="h-8 w-36 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {(Object.keys(TEMPLATE_KIND_LABELS) as TemplateKind[]).map((k) => (
                <SelectItem key={k} value={k} className="text-xs">
                  {TEMPLATE_KIND_LABELS[k]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          {/* Retention years */}
          <div className="flex items-center gap-1.5">
            <Label className="text-xs text-muted-foreground whitespace-nowrap">Retention</Label>
            <Select
              value={String(retentionYears)}
              onValueChange={(v) => setRetentionYears(Number(v))}
            >
              <SelectTrigger className="h-8 w-20 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {RETENTION_YEARS_OPTIONS.map((y) => (
                  <SelectItem key={y} value={String(y)} className="text-xs">
                    {y} yr
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Language */}
          <Select value={language} onValueChange={(v) => { if (v) setLanguage(v) }}>
            <SelectTrigger className="h-8 w-20 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="en" className="text-xs">EN</SelectItem>
              <SelectItem value="de" className="text-xs">DE</SelectItem>
              <SelectItem value="fr" className="text-xs">FR</SelectItem>
              <SelectItem value="es" className="text-xs">ES</SelectItem>
              <SelectItem value="it" className="text-xs">IT</SelectItem>
              <SelectItem value="nl" className="text-xs">NL</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Toggles */}
        <div className="flex shrink-0 items-center gap-4">
          <div className="flex items-center gap-1.5">
            <Switch
              id="requires-guardian"
              checked={requiresGuardian}
              onCheckedChange={setRequiresGuardian}
              aria-label="Requires guardian"
            />
            <Label htmlFor="requires-guardian" className="text-xs cursor-pointer">
              Guardian
            </Label>
          </div>
          <div className="flex items-center gap-1.5">
            <Switch
              id="required-for-booking"
              checked={requiredForBooking}
              onCheckedChange={setRequiredForBooking}
              aria-label="Required for booking"
            />
            <Label htmlFor="required-for-booking" className="text-xs cursor-pointer">
              Req. booking
            </Label>
          </div>
          <div className="flex items-center gap-1.5">
            <Switch
              id="is-default"
              checked={isDefault}
              onCheckedChange={setIsDefault}
              aria-label="Set as default"
            />
            <Label htmlFor="is-default" className="text-xs cursor-pointer">
              Default
            </Label>
          </div>
        </div>

        {/* Actions */}
        <div className="flex shrink-0 items-center gap-2">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => setShowPreview((v) => !v)}
            className="h-8 gap-1.5 text-xs"
          >
            {showPreview ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
            {showPreview ? 'Builder' : 'Preview'}
          </Button>

          {submissionCount > 0 && templateId && (
            <span className="text-xs text-muted-foreground">
              {submissionCount} submissions
            </span>
          )}

          <Button
            type="button"
            size="sm"
            onClick={handleSave}
            disabled={isPending}
            className="h-8 gap-1.5 text-xs"
          >
            {isPending ? (
              <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Save className="h-3.5 w-3.5" />
            )}
            {templateId ? 'Save' : 'Create'}
          </Button>
        </div>
      </div>

      {/* ── Body ─────────────────────────────────────────────────── */}
      {showPreview ? (
        <div className="flex-1 overflow-hidden">
          <TemplatePreview
            templateName={name || 'Untitled Form'}
            sections={sections}
            requiresGuardian={requiresGuardian}
          />
        </div>
      ) : (
        <div className="flex flex-1 min-h-0 overflow-hidden">
          {/* LEFT — palette + section list + note mappings */}
          <div className="flex w-[340px] shrink-0 flex-col border-r border-border overflow-hidden">
            <ScrollArea className="flex-1">
              <div className="space-y-4 p-4">
                {/* Section list (when non-empty) */}
                {sections.length > 0 && (
                  <div className="space-y-2">
                    <p className="px-1 text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Sections ({sections.length})
                    </p>
                    <SectionList sections={sections} onChange={setSections} />
                  </div>
                )}

                {/* Palette */}
                <SectionPalette onAddSection={handleAddSection} />

                {/* ── Note propagation mappings ──────────────────── */}
                {sections.length > 0 && (
                  <div className="space-y-2">
                    <button
                      type="button"
                      className="flex w-full items-center gap-2 px-1 text-xs font-medium uppercase tracking-wider text-muted-foreground hover:text-foreground transition-colors"
                      onClick={() => setShowNoteMappings((v) => !v)}
                    >
                      <Activity className="h-3 w-3" aria-hidden="true" />
                      Health Note Mapping
                      {activeMappingCount > 0 && (
                        <span className="ml-auto text-primary font-semibold normal-case tracking-normal">
                          {activeMappingCount} active
                        </span>
                      )}
                    </button>

                    {showNoteMappings && (
                      <div className="space-y-1.5">
                        {propagatableSections.length === 0 ? (
                          <p className="px-1 text-xs text-muted-foreground">
                            Add text, checkbox, date, or dropdown sections to enable note propagation.
                          </p>
                        ) : (
                          propagatableSections.map((section) => (
                            <NoteMappingEditor
                              key={section.id}
                              templateId={templateId ?? ''}
                              sectionId={section.id}
                              sectionLabel={section.label || `(${section.kind})`}
                              existingMapping={noteMappings[section.id] ?? null}
                              onMappingChange={handleMappingChange}
                            />
                          ))
                        )}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </ScrollArea>
          </div>

          {/* RIGHT — live preview */}
          <div className="flex-1 min-w-0 bg-[var(--color-builder-preview-bg,hsl(var(--muted)/0.3))]">
            <TemplatePreview
              templateName={name || 'Untitled Form'}
              sections={sections}
              requiresGuardian={requiresGuardian}
            />
          </div>
        </div>
      )}

      {/* ── Immutability violation dialog ────────────────────────── */}
      <Dialog
        open={immutabilityDialog.open}
        onOpenChange={(open) => {
          if (!open) setImmutabilityDialog({ open: false, newVersion: 0 })
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-warning" />
              Publish as New Version?
            </DialogTitle>
            <DialogDescription>
              This template has existing submissions. Saving changes will publish it as{' '}
              <strong>version {immutabilityDialog.newVersion}</strong>. Existing submissions keep
              their snapshot — only new consent requests will use the updated template.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setImmutabilityDialog({ open: false, newVersion: 0 })}
            >
              Cancel
            </Button>
            <Button onClick={handlePublishNewVersion} disabled={isPending}>
              {isPending && <Loader2 aria-hidden="true" className="mr-2 h-4 w-4 animate-spin" />}
              Publish v{immutabilityDialog.newVersion}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

