import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createPublicClient } from '@/lib/supabase/public'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { publicBookingCreateRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { sendEmail } from '@/lib/email/resend'
import { logger } from '@/lib/logger'

const CreatePublicBookingSchema = z.object({
  token: z.string().uuid('token must be a valid UUID'),
  studio_slug: z.string().min(1).max(100),
  service_id: z.string().uuid(),
  artist_id: z.string().uuid(),
  scheduled_at: z.string().datetime(),
  client_data: z.object({
    first_name: z.string().min(1).max(100),
    last_name: z.string().max(100).optional(),
    email: z.string().email().max(254),
    phone: z.string().max(30).optional(),
  }),
  // Part D: optional pre-booking consent submission ID
  consent_submission_id: z.string().uuid().optional(),
})

export async function POST(request: NextRequest) {
  const ip = getClientIp(request)
  const { success } = await publicBookingCreateRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreatePublicBookingSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const {
    token,
    studio_slug,
    service_id,
    artist_id,
    scheduled_at,
    client_data,
    consent_submission_id,
  } = parsed.data

  try {
    const supabase = createPublicClient()
    const { data, error } = await supabase.rpc('public_create_booking', {
      p_token: token,
      p_studio_slug: studio_slug,
      p_service_id: service_id,
      p_artist_id: artist_id,
      p_scheduled_at: scheduled_at,
      p_client_data: client_data,
    })

    if (error) {
      logger.error({ err: error, studio_slug }, 'public booking create RPC failed')
      return NextResponse.json({ error: 'Failed to create booking' }, { status: 500 })
    }

    // RPC returns HTTP 200 always — check the payload for error key
    const result = data as Record<string, unknown>
    if (result && typeof result === 'object' && 'error' in result) {
      if (result.error === 'time_slot_unavailable') {
        return NextResponse.json(
          { error: 'That time slot is no longer available. Please choose another.' },
          { status: 409 }
        )
      }
      return NextResponse.json({ error: 'Unable to complete booking. Please try again.' }, { status: 400 })
    }

    const bookingToken = result['booking_token'] as string
    const bookingId = result['booking_id'] as string | undefined
    const clientId = result['client_id'] as string | undefined

    // ── Post-booking intake flow ─────────────────────────────────────────────
    // Fire-and-forget after the booking is confirmed — never blocks the response.
    void triggerPostBookingIntake({
      studioSlug: studio_slug,
      bookingToken,
      bookingId,
      clientId,
      clientEmail: client_data.email,
      clientFirstName: client_data.first_name,
      scheduledAt: scheduled_at,
      serviceId: service_id,
      consentSubmissionId: consent_submission_id,
    }).catch((err: unknown) => {
      logger.error({ err, bookingToken }, 'post-booking intake trigger failed (non-fatal)')
    })

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'public booking POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

// ── Post-booking intake helper ───────────────────────────────────────────────

interface IntakeTriggerParams {
  studioSlug: string
  bookingToken: string
  bookingId: string | undefined
  clientId: string | undefined
  clientEmail: string
  clientFirstName: string
  scheduledAt: string
  serviceId: string
  consentSubmissionId: string | undefined
}

async function triggerPostBookingIntake(params: IntakeTriggerParams): Promise<void> {
  const serviceRole = createServiceRoleClient()

  // 1. Fetch studio with intake policy + service name in one shot
  const { data: studio, error: studioErr } = await serviceRole
    .from('studios')
    .select(
      'id, name, require_intake_before_booking, default_intake_template_id, intake_timing',
    )
    .eq('slug', params.studioSlug)
    .single()

  if (studioErr ?? !studio) {
    logger.warn({ studioSlug: params.studioSlug }, 'intake trigger: studio not found')
    return
  }

  // If intake is not required for this studio, nothing to do
  if (!studio.require_intake_before_booking) return
  if (!studio.default_intake_template_id) return

  // Resolve booking_id + client_id if the RPC didn't return them
  let resolvedBookingId = params.bookingId
  let resolvedClientId = params.clientId

  if (!resolvedBookingId || !resolvedClientId) {
    const { data: bookingData, error: bookingErr } = await serviceRole
      .from('bookings')
      .select('id, client_id')
      .eq('booking_token', params.bookingToken)
      .single()

    if (bookingErr ?? !bookingData) {
      logger.warn({ bookingToken: params.bookingToken }, 'intake trigger: booking lookup failed')
      return
    }

    resolvedBookingId = bookingData.id
    resolvedClientId = bookingData.client_id
  }

  // Link pre-booking consent submission to booking if provided
  if (params.consentSubmissionId && resolvedBookingId) {
    const { error: linkErr } = await serviceRole
      .from('consent_form_submissions')
      .update({ booking_id: resolvedBookingId })
      .eq('id', params.consentSubmissionId)
      .is('booking_id', null)

    if (linkErr) {
      logger.warn(
        { err: linkErr, submissionId: params.consentSubmissionId },
        'intake trigger: submission booking link failed (non-fatal)',
      )
    }
    // Pre-booking flow done — the form was already submitted
    return
  }

  // Post-booking flow: create consent request + send email
  if (studio.intake_timing !== 'post_booking') return

  // Fetch service name for email subject
  const { data: serviceData } = await serviceRole
    .from('services')
    .select('name')
    .eq('id', params.serviceId)
    .single()

  const serviceName = serviceData?.name ?? 'your appointment'

  // Create consent_form_requests row
  const requestToken = crypto.randomUUID()
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString()

  const { error: insertErr } = await serviceRole
    .from('consent_form_requests')
    .insert({
      studio_id: studio.id,
      template_id: studio.default_intake_template_id,
      booking_id: resolvedBookingId,
      client_id: resolvedClientId ?? null,
      sent_to_email: params.clientEmail,
      request_token: requestToken,
      status: 'pending',
      sent_at: new Date().toISOString(),
      expires_at: expiresAt,
    })

  if (insertErr) {
    logger.error({ err: insertErr, resolvedBookingId }, 'intake trigger: consent request insert failed')
    return
  }

  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://app.inkos.app'
  const intakeFormUrl = `${appUrl}/consent/${requestToken}`

  // Send email via Resend
  try {
    await sendEmail({
      to: params.clientEmail,
      template: 'intake_request',
      data: {
        studioName: studio.name,
        clientFirstName: params.clientFirstName,
        serviceName,
        scheduledAt: params.scheduledAt,
        intakeFormUrl,
      },
    })
  } catch (emailErr) {
    // Non-fatal — request row exists, client can be resent manually
    logger.error({ err: emailErr, requestToken }, 'intake trigger: email send failed (non-fatal)')
  }

  logger.info(
    { requestToken, studioId: studio.id, resolvedBookingId },
    'intake trigger: consent request created and email sent',
  )
}

