/**
 * GET /api/public/studios/[slug]/intake-policy
 *
 * Returns the intake form policy for a studio (anon-accessible).
 * Used by the public booking page to determine whether to show the pre-booking
 * intake step and which template to render.
 *
 * Rate-limited by publicBookingReadRatelimit.
 */
import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createPublicClient } from '@/lib/supabase/public'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import type { ConsentSection } from '@/types/consent'
import type { Json } from '@/lib/supabase/types'

interface Params {
  params: Promise<{ slug: string }>
}

export interface IntakePolicyResponse {
  require_intake_before_booking: boolean
  intake_timing: 'pre_booking' | 'post_booking'
  template: {
    id: string
    name: string
    sections: ConsentSection[]
    requires_guardian: boolean
  } | null
}

export async function GET(request: NextRequest, { params }: Params) {
  const ip = getClientIp(request)
  const { success } = await publicBookingReadRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { slug } = await params
  if (!z.string().min(1).max(100).safeParse(slug).success) {
    return NextResponse.json({ error: 'Invalid slug' }, { status: 400 })
  }

  try {
    const supabase = createPublicClient()

    // Fetch studio intake policy fields
    const { data: studio, error: studioErr } = await supabase
      .from('studios')
      .select('require_intake_before_booking, default_intake_template_id, intake_timing')
      .eq('slug', slug)
      .single()

    if (studioErr ?? !studio) {
      logger.error({ err: studioErr, slug }, 'intake-policy: studio not found')
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    if (!studio.require_intake_before_booking || !studio.default_intake_template_id) {
      const payload: IntakePolicyResponse = {
        require_intake_before_booking: false,
        intake_timing: studio.intake_timing,
        template: null,
      }
      return NextResponse.json({ data: payload })
    }

    // Fetch default intake template (only public-safe fields)
    const { data: template, error: templateErr } = await supabase
      .from('consent_form_templates')
      .select('id, name, sections, requires_guardian')
      .eq('id', studio.default_intake_template_id)
      .eq('is_active', true)
      .single()

    if (templateErr ?? !template) {
      // Template not found — treat as no intake required (graceful degradation)
      logger.warn(
        { templateId: studio.default_intake_template_id, slug },
        'intake-policy: default template not found, skipping intake step',
      )
      const payload: IntakePolicyResponse = {
        require_intake_before_booking: false,
        intake_timing: studio.intake_timing,
        template: null,
      }
      return NextResponse.json({ data: payload })
    }

    const payload: IntakePolicyResponse = {
      require_intake_before_booking: true,
      intake_timing: studio.intake_timing,
      template: {
        id: template.id,
        name: template.name,
        sections: template.sections as unknown as ConsentSection[],
        requires_guardian: template.requires_guardian,
      },
    }

    return NextResponse.json({ data: payload })
  } catch (err) {
    logger.error({ err, slug }, 'intake-policy GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

// Needed for Supabase type satisfaction — sections is Json in DB, ConsentSection[] at runtime
export type { Json }

/**
 * POST /api/public/consent/pre-booking
 *
 * Handles the pre-booking intake flow:
 * 1. Upsert client row by (studio_id, email) — or create fresh
 * 2. Create consent_form_requests row (status = 'pending', no booking_id yet)
 * 3. Delegate to submit_consent_form RPC → returns submission_id
 * 4. Upload signature PNG
 * 5. Return submission_id — booking page passes this to /api/public/bookings
 *    which links it to the booking once created
 *
 * Rate-limited: 3 per minute per IP (same as regular consent submit).
 */
import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { createPublicClient } from '@/lib/supabase/public'
import { createServiceRoleClient } from '@/lib/supabase/server'
import type { Json } from '@/lib/supabase/types'
import { publicConsentSubmitRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { validateSignatureBase64, uploadSignaturePng } from '@/lib/consent/validate-signature'
import { enqueueJob } from '@/lib/queue'
import { logger } from '@/lib/logger'

const PreBookingSubmitSchema = z.object({
  studio_slug: z.string().min(1).max(100),
  template_id: z.string().uuid(),
  answers: z.record(z.string(), z.unknown()),
  signature_png_base64: z.string().min(1),
  signer_name: z.string().min(1).max(200),
  signer_email: z.string().email().max(254),
  signer_phone: z.string().max(30).nullable().optional(),
  signer_dob: z.string().nullable().optional(),
})

export async function POST(request: NextRequest) {
  const ip = getClientIp(request)
  const userAgent = request.headers.get('user-agent') ?? null
  const { success } = await publicConsentSubmitRatelimit.limit(ip)
  if (!success) {
    return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })
  }

  let rawBody: unknown
  try {
    rawBody = await request.json()
  } catch {
    return Response.json({ error: 'invalid_json' }, { status: 400 })
  }

  const parsed = PreBookingSubmitSchema.safeParse(rawBody)
  if (!parsed.success) {
    return Response.json({ error: 'validation_error', details: parsed.error.flatten() }, { status: 400 })
  }

  const body = parsed.data

  // Validate signature
  const sigValidation = validateSignatureBase64(body.signature_png_base64, 'signature')
  if (!sigValidation.valid || !sigValidation.buffer) {
    return Response.json({ error: sigValidation.error }, { status: 400 })
  }

  const serviceRole = createServiceRoleClient()

  // 1. Fetch studio_id from slug
  const { data: studio, error: studioErr } = await serviceRole
    .from('studios')
    .select('id, require_intake_before_booking, default_intake_template_id')
    .eq('slug', body.studio_slug)
    .single()

  if (studioErr ?? !studio) {
    return Response.json({ error: 'studio_not_found' }, { status: 404 })
  }

  // Safety: verify the template_id matches the studio's configured intake template
  if (studio.default_intake_template_id !== body.template_id) {
    return Response.json({ error: 'invalid_template' }, { status: 400 })
  }

  // 2. Upsert client row by (studio_id, email) — service role bypasses RLS
  const nameParts = body.signer_name.trim().split(/\s+/)
  const firstName = nameParts[0] ?? body.signer_name
  const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : null

  // Try to find existing client by email in this studio
  const { data: existingClient } = await serviceRole
    .from('clients')
    .select('id')
    .eq('studio_id', studio.id)
    .eq('email', body.signer_email)
    .maybeSingle()

  let clientId: string

  if (existingClient) {
    clientId = existingClient.id
  } else {
    const { data: newClient, error: clientErr } = await serviceRole
      .from('clients')
      .insert({
        studio_id: studio.id,
        first_name: firstName,
        last_name: lastName,
        email: body.signer_email,
        phone: body.signer_phone ?? null,
        source: 'public',
      })
      .select('id')
      .single()

    if (clientErr ?? !newClient) {
      logger.error({ err: clientErr, studioId: studio.id }, 'pre-booking consent: client insert failed')
      return Response.json({ error: 'client_creation_failed' }, { status: 500 })
    }

    clientId = newClient.id
  }

  // 3. Create consent_form_requests row (no booking_id yet — linked later)
  const requestToken = crypto.randomUUID()
  const expiresAt = new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString() // 2 hour window for pre-booking

  const { error: reqInsertErr } = await serviceRole
    .from('consent_form_requests')
    .insert({
      studio_id: studio.id,
      template_id: body.template_id,
      booking_id: null,
      client_id: clientId,
      sent_to_email: body.signer_email,
      request_token: requestToken,
      status: 'pending',
      expires_at: expiresAt,
    })

  if (reqInsertErr) {
    logger.error({ err: reqInsertErr, studioId: studio.id }, 'pre-booking consent: request insert failed')
    return Response.json({ error: 'request_creation_failed' }, { status: 500 })
  }

  // 4. Submit the consent form via the existing public RPC
  const supabase = createPublicClient()
  const submitPayload = {
    p_request_token: requestToken,
    p_answers: body.answers as unknown as Json,
    p_signature_png_base64: body.signature_png_base64,
    p_signer_name: body.signer_name,
    p_signer_email: body.signer_email,
    p_signer_phone: body.signer_phone ?? null,
    p_signer_dob: body.signer_dob ?? null,
    p_guardian: null,
    p_ink_records: null,
    p_ip_address: ip,
    p_user_agent: userAgent,
  }

  const { data: rpcResult, error: rpcError } = await supabase.rpc('submit_consent_form', submitPayload)

  if (rpcError) {
    logger.error({ err: rpcError, requestToken }, 'pre-booking consent: submit RPC failed')
    return Response.json({ error: 'submission_failed' }, { status: 500 })
  }

  const result = rpcResult as Record<string, unknown>
  if (result['error']) {
    const httpStatus =
      result['error'] === 'already_signed' ? 409
      : result['error'] === 'expired' ? 410
      : result['error'] === 'request_not_found' ? 404
      : 500
    return Response.json(rpcResult, { status: httpStatus })
  }

  const signaturePath = result['signature_path'] as string
  const submissionId = result['submission_id'] as string

  // 5. Upload signature PNG
  try {
    await uploadSignaturePng(serviceRole, sigValidation.buffer, signaturePath)
  } catch (err) {
    logger.error({ err, signaturePath, submissionId }, 'pre-booking consent: signature upload failed')
    return Response.json({ error: 'submission_failed' }, { status: 500 })
  }

  // 6. Enqueue PDF generation
  const studioId = signaturePath.split('/')[0] ?? studio.id
  try {
    await enqueueJob('generate-consent-pdf', { submission_id: submissionId, studio_id: studioId })
  } catch (err) {
    logger.error({ err, submissionId }, 'pre-booking consent: PDF job enqueue failed (non-fatal)')
  }

  logger.info({ submissionId, clientId, studioId }, 'pre-booking consent: submission created')

  return Response.json({
    submission_id: submissionId,
    client_id: clientId,
  })
}

'use client'

/**
 * IntakeFormStep — renders a consent/intake form inline during the public
 * booking flow (pre-booking timing). Reuses SectionRenderer and SignaturePad.
 *
 * Flow:
 * 1. Renders each section of the template using SectionRenderer
 * 2. Collects answers + main signature
 * 3. On submit: calls POST /api/public/consent/pre-booking
 * 4. Returns submission_id to the booking page
 */

import { useState, useCallback } from 'react'
import { Loader2, ShieldCheck } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { ScrollArea } from '@/components/ui/scroll-area'
import { SignaturePad } from '@/components/consent/SignaturePad'
import { SectionRenderer } from '@/components/consent/templates/SectionRenderer'
import { cn } from '@/lib/utils'
import type { ConsentSection, SectionAnswers, SectionAnswerValue } from '@/types/consent'

interface IntakeFormStepProps {
  studioSlug: string
  studioName: string
  templateId: string
  templateName: string
  sections: ConsentSection[]
  /** Signer info pre-filled from the client details step */
  signerName: string
  signerEmail: string
  signerPhone: string
  /** Called with submission_id after successful form submission */
  onSubmitted: (submissionId: string) => void
  /** Called if the user wants to go back */
  onBack: () => void
}

function isSectionAnswerRequired(section: ConsentSection): boolean {
  if (!section.required) return true
  return !(
    section.kind === 'heading' ||
    section.kind === 'paragraph' ||
    section.kind === 'reach_batch_record'
  )
}

function isAnswerComplete(section: ConsentSection, answers: SectionAnswers): boolean {
  if (!isSectionAnswerRequired(section)) return true
  const value = answers[section.id]
  switch (section.kind) {
    case 'checkbox':
    case 'ink_disclosure':
      return value === true
    case 'signature':
    case 'initials':
      return typeof value === 'string' && value.length > 0
    case 'text_input':
      return typeof value === 'string' && value.trim().length > 0
    case 'date':
    case 'dropdown':
      return typeof value === 'string' && value.length > 0
    case 'file_upload':
      return typeof value === 'string' && value.length > 0
    default:
      return true
  }
}

export function IntakeFormStep({
  studioSlug,
  studioName,
  templateId,
  templateName,
  sections,
  signerName,
  signerEmail,
  signerPhone,
  onSubmitted,
  onBack,
}: IntakeFormStepProps) {
  const sortedSections = [...sections].sort((a, b) => a.order - b.order)

  const [answers, setAnswers] = useState<SectionAnswers>({})
  const [mainSigPng, setMainSigPng] = useState('')
  const [signerDob, setSignerDob] = useState('')
  const [submitting, setSubmitting] = useState(false)

  // Identify required but incomplete sections for validation UI
  const requiredSections = sortedSections.filter((s) => s.required && isSectionAnswerRequired(s))
  const incompleteRequired = requiredSections.filter((s) => !isAnswerComplete(s, answers))

  const handleAnswer = useCallback((sectionId: string, value: SectionAnswerValue) => {
    setAnswers((prev) => ({ ...prev, [sectionId]: value }))
  }, [])

  const handleSubmit = useCallback(async () => {
    // Validate required sections
    if (incompleteRequired.length > 0) {
      toast.error(`Please complete all required fields (${incompleteRequired.length} remaining)`)
      return
    }

    if (!mainSigPng) {
      toast.error('Please provide your signature')
      return
    }

    setSubmitting(true)
    try {
      const res = await fetch('/api/public/consent/pre-booking', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          studio_slug: studioSlug,
          template_id: templateId,
          answers,
          signature_png_base64: mainSigPng,
          signer_name: signerName,
          signer_email: signerEmail,
          signer_phone: signerPhone || null,
          signer_dob: signerDob || null,
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to submit intake form')
      }

      const { submission_id } = await res.json() as { submission_id: string }
      onSubmitted(submission_id)
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Failed to submit intake form')
    } finally {
      setSubmitting(false)
    }
  }, [
    incompleteRequired,
    mainSigPng,
    studioSlug,
    templateId,
    answers,
    signerName,
    signerEmail,
    signerPhone,
    signerDob,
    onSubmitted,
  ])

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="space-y-1">
        <div className="flex items-center gap-2">
          <ShieldCheck className="h-4 w-4 text-primary shrink-0" aria-hidden="true" />
          <h2 className="text-base font-semibold">{templateName}</h2>
        </div>
        <p className="text-xs text-muted-foreground">
          {studioName} requires this form before confirming your booking.
          Your answers are securely stored and only visible to studio staff.
        </p>
      </div>

      {/* Date of birth (for age verification) */}
      <div className="space-y-1.5">
        <Label htmlFor="intake-dob" className="text-xs">
          Date of birth <span className="text-muted-foreground">(optional)</span>
        </Label>
        <Input
          id="intake-dob"
          type="date"
          value={signerDob}
          onChange={(e) => setSignerDob(e.target.value)}
          className="text-sm w-48"
          max={new Date().toISOString().split('T')[0]}
        />
      </div>

      {/* Form sections */}
      <div className="space-y-4">
        {sortedSections
          .filter((s) => s.kind !== 'signature' && s.kind !== 'reach_batch_record')
          .map((section) => {
            const incomplete = section.required && !isAnswerComplete(section, answers)
            return (
              <div
                key={section.id}
                className={cn(
                  'rounded-lg border p-3 transition-colors',
                  incomplete ? 'border-destructive/40 bg-destructive/5' : 'border-border/60',
                )}
              >
                <SectionRenderer
                  section={section}
                  isPreview={false}
                  answer={answers[section.id]}
                  onAnswer={(v) => handleAnswer(section.id, v)}
                />
              </div>
            )
          })}
      </div>

      {/* Signature */}
      <div className="space-y-2">
        <p className="text-sm font-medium">
          Signature <span className="text-destructive">*</span>
        </p>
        <p className="text-xs text-muted-foreground">
          By signing, you confirm you have read and agree to the above.
        </p>
        <div className={cn(
          'rounded-lg border overflow-hidden',
          !mainSigPng ? 'border-border/60' : 'border-primary/40',
        )}>
          <SignaturePad
            onCapture={setMainSigPng}
          />
        </div>
        {mainSigPng && (
          <p className="text-xs text-primary">Signature captured</p>
        )}
      </div>

      {/* Validation summary */}
      {incompleteRequired.length > 0 && (
        <div className="rounded-md border border-destructive/30 bg-destructive/5 px-3 py-2 text-xs text-destructive">
          {incompleteRequired.length} required field{incompleteRequired.length !== 1 ? 's' : ''} incomplete
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center justify-between gap-3 pt-2">
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={onBack}
          disabled={submitting}
        >
          Back
        </Button>
        <Button
          type="button"
          size="sm"
          onClick={() => void handleSubmit()}
          disabled={submitting || incompleteRequired.length > 0 || !mainSigPng}
          className="flex-1 sm:flex-none"
        >
          {submitting ? (
            <>
              <Loader2 aria-hidden="true" className="mr-2 h-4 w-4 animate-spin" />
              Submitting…
            </>
          ) : (
            'Submit & continue'
          )}
        </Button>
      </div>
    </div>
  )
}

'use client'

import { use, useState, useCallback } from 'react'
import { useKeyboardAware } from '@/hooks/useKeyboardAware'
import { useQuery, useMutation } from '@tanstack/react-query'
import { Typography } from '@/components/ui/typography'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { SlotPicker } from '@/components/booking/SlotPicker'
import { PoliciesDisclosure } from '@/components/booking/PoliciesDisclosure'
import { FileDropzone } from '@/components/booking/FileDropzone'
import { IntakeFormStep } from '@/components/public-booking/IntakeFormStep'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'
import { formatCurrency } from '@/lib/utils'
import { ChevronLeft, ChevronRight, Clock, Check, User } from 'lucide-react'
import { cn } from '@/lib/utils'
import { z } from 'zod'
import type { IntakePolicyResponse } from '@/app/api/public/studios/[slug]/intake-policy/route'

const ClientFormSchema = z.object({
  first_name: z.string().min(1, 'First name is required').max(100),
  last_name: z.string().max(100).optional(),
  email: z.string().email('Enter a valid email'),
  phone: z.string().max(30).optional(),
})

type ClientFormData = z.infer<typeof ClientFormSchema>

interface ArtistPublic {
  id: string
  display_name: string
  avatar_url: string | null
  bio: string | null
  specialties: string[]
}

interface ServicePublic {
  id: string
  name: string
  description: string | null
  duration_min: number
  base_price_cents: number
  deposit_cents: number
  deposit_required: boolean
  color: string | null
}

interface StudioPublic {
  id: string
  name: string
  slug: string
  brand_color: string | null
}

// Steps depend on whether pre-booking intake is required.
// Base steps: Artist (0), Time (1), Details (2)
// With pre-booking intake: Artist (0), Time (1), Details (2), Intake (3)
const BASE_STEPS = ['Artist', 'Time', 'Details'] as const

export default function BookServicePage({
  params,
}: {
  params: Promise<{ studioSlug: string; serviceId: string }>
}) {
  useKeyboardAware()
  const { studioSlug, serviceId } = use(params)
  const router = useRouter()

  const [step, setStep] = useState(0)
  const [selectedArtistId, setSelectedArtistId] = useState<string | null>(null)
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null)
  const [clientForm, setClientForm] = useState<ClientFormData>({
    first_name: '',
    last_name: '',
    email: '',
    phone: '',
  })
  const [formErrors, setFormErrors] = useState<Record<string, string | undefined>>({})
  // Pre-booking intake submission ID — set after IntakeFormStep completes
  const [intakeSubmissionId, setIntakeSubmissionId] = useState<string | null>(null)

  const { data: studioData } = useQuery<{ data: StudioPublic }>({
    queryKey: ['public', 'studio', studioSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}`)
      if (!res.ok) throw new Error('Studio not found')
      return res.json() as Promise<{ data: StudioPublic }>
    },
  })

  const { data: serviceData, isLoading: serviceLoading } = useQuery<{ data: ServicePublic[] }>({
    queryKey: ['public', 'services', studioData?.data.id],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/services`)
      if (!res.ok) throw new Error('Failed to load service')
      return res.json() as Promise<{ data: ServicePublic[] }>
    },
    enabled: !!studioData,
  })

  const { data: artistsData, isLoading: artistsLoading } = useQuery<{ data: ArtistPublic[] }>({
    queryKey: ['public', 'artists', studioData?.data.id],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/artists`)
      if (!res.ok) throw new Error('Failed to load artists')
      return res.json() as Promise<{ data: ArtistPublic[] }>
    },
    enabled: !!studioData,
  })

  // Fetch intake policy (anon) — only when studio is resolved
  const { data: intakePolicyData } = useQuery<{ data: IntakePolicyResponse }>({
    queryKey: ['public', 'intake-policy', studioSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/intake-policy`)
      if (!res.ok) return { data: { require_intake_before_booking: false, intake_timing: 'post_booking' as const, template: null } }
      return res.json() as Promise<{ data: IntakePolicyResponse }>
    },
    enabled: !!studioData,
    staleTime: 5 * 60 * 1000, // 5 min cache — policy rarely changes
  })

  const studio = studioData?.data
  const service = serviceData?.data.find((s) => s.id === serviceId)
  const artists = artistsData?.data ?? []
  const brandColor = studio?.brand_color ?? null
  const intakePolicy = intakePolicyData?.data

  // Whether we need a pre-booking intake step
  const needsPreBookingIntake =
    intakePolicy?.require_intake_before_booking === true &&
    intakePolicy.intake_timing === 'pre_booking' &&
    intakePolicy.template !== null

  const steps = needsPreBookingIntake
    ? ([...BASE_STEPS, 'Intake'] as const)
    : BASE_STEPS

  const bookMutation = useMutation({
    mutationFn: async () => {
      if (!selectedArtistId || !selectedSlot || !service) {
        throw new Error('Missing required booking data')
      }

      const token = crypto.randomUUID()
      const body: Record<string, unknown> = {
        token,
        studio_slug: studioSlug,
        service_id: serviceId,
        artist_id: selectedArtistId,
        scheduled_at: selectedSlot,
        client_data: {
          first_name: clientForm.first_name,
          last_name: clientForm.last_name || undefined,
          email: clientForm.email,
          phone: clientForm.phone || undefined,
        },
      }

      // Link pre-booking intake submission if present
      if (intakeSubmissionId) {
        body['consent_submission_id'] = intakeSubmissionId
      }

      const res = await fetch('/api/public/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        if (res.status === 409) {
          throw new Error('That time slot is no longer available. Please pick another time.')
        }
        throw new Error(err.error ?? 'Failed to create booking')
      }

      const { data } = await res.json() as { data: { booking_token: string } }
      return data.booking_token
    },
    onSuccess: (bookingToken) => {
      router.push(`/book/${studioSlug}/confirmation/${bookingToken}`)
    },
    onError: (err: Error) => {
      if (err.message.includes('time slot')) {
        toast.error(err.message)
        setStep(1) // back to time picker
        setSelectedSlot(null)
      } else {
        toast.error(err.message)
      }
    },
  })

  const validateClientForm = useCallback((): boolean => {
    const result = ClientFormSchema.safeParse(clientForm)
    if (!result.success) {
      const errors: Record<string, string | undefined> = {}
      result.error.issues.forEach((issue) => {
        const key = issue.path[0] as keyof ClientFormData
        if (!errors[key]) errors[key] = issue.message
      })
      setFormErrors(errors)
      return false
    }
    setFormErrors({})
    return true
  }, [clientForm])

  const handleNextOrBook = useCallback(() => {
    const lastStep = steps.length - 1

    if (step === 2) {
      // Details step — validate form
      if (!validateClientForm()) return
      if (needsPreBookingIntake) {
        // Proceed to intake step
        setStep(3)
      } else {
        // No intake required — book directly
        bookMutation.mutate()
      }
      return
    }

    if (step < lastStep) {
      setStep((s) => s + 1)
    } else {
      // Final step (only reached if intake was shown and completed via IntakeFormStep)
      bookMutation.mutate()
    }
  }, [step, steps.length, validateClientForm, needsPreBookingIntake, bookMutation])

  const canProceed =
    (step === 0 && !!selectedArtistId) ||
    (step === 1 && !!selectedSlot) ||
    step === 2 ||
    (step === 3 && !!intakeSubmissionId)

  if (serviceLoading || !service) {
    return (
      <div className="max-w-lg mx-auto px-4 py-10 space-y-4">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-24 w-full" />
        <Skeleton className="h-64 w-full" />
      </div>
    )
  }

  // Intake step is rendered separately (no sticky bottom bar — it has its own submit)
  if (step === 3 && needsPreBookingIntake && intakePolicy?.template) {
    return (
      <div
        className="min-h-svh"
        style={brandColor ? ({ '--booking-brand': brandColor } as React.CSSProperties) : undefined}
      >
        {/* Header */}
        <div
          className="border-b border-border/40"
          style={
            brandColor
              ? { background: `linear-gradient(135deg, ${brandColor}15, ${brandColor}05)` }
              : undefined
          }
        >
          <div className="max-w-lg mx-auto px-4 py-4">
            <p className="text-xs text-muted-foreground">{studio?.name}</p>
            <p className="text-sm font-medium">{service.name}</p>
          </div>

          {/* Step indicator */}
          <div className="max-w-lg mx-auto px-4 pb-4">
            <div className="flex items-center gap-2">
              {steps.map((label, index) => (
                <div key={label} className="flex items-center gap-2">
                  <div className="flex items-center gap-1.5">
                    <div
                      className={cn(
                        'h-5 w-5 rounded-full flex items-center justify-center text-xs font-medium transition-all',
                        index < step
                          ? 'bg-primary text-primary-foreground'
                          : index === step
                            ? 'border-2 border-primary text-primary'
                            : 'border-2 border-border text-muted-foreground'
                      )}
                    >
                      {index < step ? <Check className="h-3 w-3" /> : index + 1}
                    </div>
                    <span
                      className={cn(
                        'text-xs font-medium',
                        index === step ? 'text-foreground' : 'text-muted-foreground'
                      )}
                    >
                      {label}
                    </span>
                  </div>
                  {index < steps.length - 1 && (
                    <div
                      className={cn(
                        'h-px flex-1 min-w-[16px]',
                        index < step ? 'bg-primary' : 'bg-border'
                      )}
                    />
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Intake form */}
        <div className="max-w-lg mx-auto px-4 py-6">
          <IntakeFormStep
            studioSlug={studioSlug}
            studioName={studio?.name ?? ''}
            templateId={intakePolicy.template.id}
            templateName={intakePolicy.template.name}
            sections={intakePolicy.template.sections}
            signerName={`${clientForm.first_name} ${clientForm.last_name ?? ''}`.trim()}
            signerEmail={clientForm.email}
            signerPhone={clientForm.phone ?? ''}
            onSubmitted={(submissionId) => {
              setIntakeSubmissionId(submissionId)
              bookMutation.mutate()
            }}
            onBack={() => setStep(2)}
          />
        </div>
      </div>
    )
  }

  return (
    <div
      className="min-h-svh"
      style={brandColor ? ({ '--booking-brand': brandColor } as React.CSSProperties) : undefined}
    >
      {/* Header */}
      <div
        className="border-b border-border/40"
        style={
          brandColor
            ? { background: `linear-gradient(135deg, ${brandColor}15, ${brandColor}05)` }
            : undefined
        }
      >
        <div className="max-w-lg mx-auto px-4 py-4 flex items-center gap-3">
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 shrink-0"
            onClick={() => (step > 0 ? setStep((s) => s - 1) : router.push(`/book/${studioSlug}`))}
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>

          <div className="min-w-0">
            <p className="text-xs text-muted-foreground">{studio?.name}</p>
            <div className="flex items-center gap-1.5">
              {service.color && (
                <span
                  className="h-2 w-2 rounded-full shrink-0"
                  style={{ backgroundColor: service.color }}
                />
              )}
              <Typography variant="h2" as="h1" className="truncate">{service.name}</Typography>
            </div>
            <div className="flex items-center gap-2 flex-wrap">
              <p className="text-xs text-muted-foreground flex items-center gap-1">
                <Clock className="h-3 w-3" />
                {service.duration_min} min · {formatCurrency(service.base_price_cents)}
              </p>
              {service.deposit_required && service.deposit_cents > 0 && (
                <span className="inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium bg-warning/10 text-warning-foreground border border-warning/20">
                  {formatCurrency(service.deposit_cents)} deposit
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Step indicator */}
        <div className="max-w-lg mx-auto px-4 pb-4">
          <div className="flex items-center gap-2">
            {steps.map((label, index) => (
              <div key={label} className="flex items-center gap-2">
                <div className="flex items-center gap-1.5">
                  <div
                    className={cn(
                      'h-5 w-5 rounded-full flex items-center justify-center text-xs font-medium transition-all',
                      index < step
                        ? 'bg-primary text-primary-foreground'
                        : index === step
                          ? 'border-2 border-primary text-primary'
                          : 'border-2 border-border text-muted-foreground'
                    )}
                  >
                    {index < step ? <Check className="h-3 w-3" /> : index + 1}
                  </div>
                  <span
                    className={cn(
                      'text-xs font-medium',
                      index === step ? 'text-foreground' : 'text-muted-foreground'
                    )}
                  >
                    {label}
                  </span>
                </div>
                {index < steps.length - 1 && (
                  <div
                    className={cn(
                      'h-px flex-1 min-w-[16px]',
                      index < step ? 'bg-primary' : 'bg-border'
                    )}
                  />
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Step content */}
      <div className="max-w-lg mx-auto px-4 py-6 space-y-4">
        {/* Step 0: Artist */}
        {step === 0 && (
          <div className="space-y-3">
            <Typography variant="h2">Choose an artist</Typography>
            {artistsLoading ? (
              <div className="space-y-2">
                {Array.from({ length: 3 }).map((_, i) => (
                  <Skeleton key={i} className="h-16 w-full rounded-xl" />
                ))}
              </div>
            ) : artists.length === 0 ? (
              <p className="text-sm text-muted-foreground">No artists available.</p>
            ) : (
              <div className="space-y-2">
                {artists.map((artist) => (
                  <button
                    key={artist.id}
                    className={cn(
                      'w-full flex items-center gap-3 rounded-xl border p-3 text-left transition-all hover:bg-muted/50',
                      selectedArtistId === artist.id
                        ? 'border-primary bg-primary/5'
                        : 'border-border/60'
                    )}
                    onClick={() => setSelectedArtistId(artist.id)}
                  >
                    <div className="h-10 w-10 rounded-full bg-muted flex items-center justify-center shrink-0 overflow-hidden">
                      {artist.avatar_url ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                          src={artist.avatar_url}
                          alt={artist.display_name}
                          className="h-full w-full object-cover"
                        />
                      ) : (
                        <User className="h-4 w-4 text-muted-foreground" />
                      )}
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-medium">{artist.display_name}</p>
                      {artist.specialties.length > 0 && (
                        <p className="text-xs text-muted-foreground truncate">
                          {artist.specialties.slice(0, 2).join(', ')}
                        </p>
                      )}
                    </div>
                    {selectedArtistId === artist.id && (
                      <Check className="h-4 w-4 text-primary ml-auto shrink-0" />
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Step 1: Time */}
        {step === 1 && (
          <div className="space-y-3">
            <Typography variant="h2">Pick a time</Typography>
            <SlotPicker
              artistId={selectedArtistId}
              serviceId={serviceId}
              selectedSlot={selectedSlot}
              onSelectSlot={setSelectedSlot}
            />
          </div>
        )}

        {/* Step 2: Client details */}
        {step === 2 && (
          <div className="space-y-4">
            <Typography variant="h2">Your details</Typography>

            {/* Booking summary */}
            {selectedSlot && (
              <div className="rounded-lg bg-muted/40 border border-border/60 p-3 space-y-1 text-sm">
                <p className="font-medium text-xs text-muted-foreground uppercase tracking-wide">Summary</p>
                <p>{service.name}</p>
                <p className="text-xs text-muted-foreground tabular-nums">
                  {new Date(selectedSlot).toLocaleDateString('en-US', {
                    weekday: 'short',
                    month: 'short',
                    day: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit',
                  })}
                </p>
                <p className="font-medium tabular-nums">{formatCurrency(service.base_price_cents)}</p>
                {service.deposit_required && service.deposit_cents > 0 && (
                  <p className="text-xs text-warning dark:text-warning-foreground">
                    Deposit required: {formatCurrency(service.deposit_cents)}
                  </p>
                )}
              </div>
            )}

            {/* Client form */}
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label htmlFor="first_name" className="text-xs">First name *</Label>
                  <Input
                    id="first_name"
                    value={clientForm.first_name}
                    onChange={(e) => {
                      setClientForm((p) => ({ ...p, first_name: e.target.value }))
                      if (formErrors.first_name) setFormErrors((p) => ({ ...p, first_name: undefined }))
                    }}
                    placeholder="Jane"
                    className={cn('text-sm', formErrors.first_name && 'border-destructive')}
                  />
                  {formErrors.first_name && (
                    <p className="text-xs text-destructive">{formErrors.first_name}</p>
                  )}
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="last_name" className="text-xs">Last name</Label>
                  <Input
                    id="last_name"
                    value={clientForm.last_name}
                    onChange={(e) => setClientForm((p) => ({ ...p, last_name: e.target.value }))}
                    placeholder="Doe"
                    className="text-sm"
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="pub_email" className="text-xs">Email *</Label>
                <Input
                  id="pub_email"
                  type="email"
                  value={clientForm.email}
                  onChange={(e) => {
                    setClientForm((p) => ({ ...p, email: e.target.value }))
                    if (formErrors.email) setFormErrors((p) => ({ ...p, email: undefined }))
                  }}
                  placeholder="jane@example.com"
                  className={cn('text-sm', formErrors.email && 'border-destructive')}
                />
                {formErrors.email && (
                  <p className="text-xs text-destructive">{formErrors.email}</p>
                )}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="pub_phone" className="text-xs">Phone</Label>
                <Input
                  id="pub_phone"
                  type="tel"
                  value={clientForm.phone}
                  onChange={(e) => setClientForm((p) => ({ ...p, phone: e.target.value }))}
                  placeholder="+1 (555) 000-0000"
                  className="text-sm"
                />
              </div>
            </div>

            {/* Reference images upload */}
            <FileDropzone
              label="Reference images (optional)"
              hint="Share inspiration photos for your tattoo — PNG, JPG up to 10MB"
              maxFiles={5}
            />

            {/* Deposit notice */}
            {service.deposit_required && service.deposit_cents > 0 && (
              <div className="rounded-lg border border-warning/20 bg-warning/5 p-3">
                <p className="text-sm font-medium text-warning-foreground">
                  Deposit required: {formatCurrency(service.deposit_cents)}
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  You&apos;ll be prompted to pay the deposit on the confirmation page.
                </p>
              </div>
            )}

            {/* Intake form notice */}
            {needsPreBookingIntake && (
              <div className="rounded-lg border border-primary/20 bg-primary/5 p-3">
                <p className="text-sm font-medium text-foreground">
                  Intake form required
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  After entering your details, you&apos;ll complete a short intake form before
                  your booking is confirmed.
                </p>
              </div>
            )}

            {/* Policies disclosure */}
            <PoliciesDisclosure
              depositCents={service.deposit_cents}
            />
          </div>
        )}

        {/* Spacer for sticky footer */}
        <div className="h-20 sm:h-0" />
      </div>

      {/* Sticky bottom CTA bar */}
      <div
        className="fixed bottom-0 left-0 right-0 bg-background border-t border-border/40 px-4 py-3 flex items-center justify-between gap-3 sm:relative sm:bottom-auto sm:left-auto sm:right-auto sm:bg-transparent sm:border-t-0 sm:px-0 sm:py-4"
        style={{ paddingBottom: 'max(0.75rem, env(safe-area-inset-bottom))' }}
      >
        <Button
          variant="outline"
          size="sm"
          onClick={() =>
            step > 0 ? setStep((s) => s - 1) : router.push(`/book/${studioSlug}`)
          }
        >
          <ChevronLeft className="h-4 w-4 mr-1" />
          {step === 0 ? 'Back' : 'Previous'}
        </Button>

        <Button
          disabled={!canProceed || bookMutation.isPending}
          onClick={handleNextOrBook}
          className="flex-1 sm:flex-none"
        >
          {bookMutation.isPending
            ? 'Booking...'
            : step === 2 && needsPreBookingIntake
              ? 'Next: Intake form'
              : step === steps.length - 1 || (step === 2 && !needsPreBookingIntake)
                ? 'Confirm booking'
                : 'Next'}
          {step < 2 && !bookMutation.isPending && (
            <ChevronRight className="h-4 w-4 ml-1" />
          )}
        </Button>
      </div>
    </div>
  )
}

